create table public.teacher_invite_codes(id uuid primary key default gen_random_uuid(),code_hash bytea not null unique,label text,created_by uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),used_by uuid references auth.users(id) on delete set null,used_at timestamptz);
create index teacher_invite_codes_created_by_idx on public.teacher_invite_codes(created_by);
create index teacher_invite_codes_used_by_idx on public.teacher_invite_codes(used_by) where used_by is not null;
alter table public.teacher_invite_codes enable row level security;
grant select on public.teacher_invite_codes to authenticated;
create policy teacher_invites_admin_select on public.teacher_invite_codes for select to authenticated using(private.current_app_role()='admin');
create or replace function public.admin_create_teacher_invite(raw_code text,invite_label text default null) returns void language plpgsql security definer set search_path='' as $body$ begin if private.current_app_role()<>'admin' then raise exception '관리자 권한이 필요합니다.'; end if; if length(trim(raw_code))<6 then raise exception '초대코드는 6자 이상이어야 합니다.'; end if; insert into public.teacher_invite_codes(code_hash,label,created_by) values(extensions.digest(convert_to(lower(trim(raw_code)),'UTF8'),'sha256'),nullif(trim(invite_label),''),auth.uid()); end; $body$;
revoke all on function public.admin_create_teacher_invite(text,text) from public,anon; grant execute on function public.admin_create_teacher_invite(text,text) to authenticated;
create or replace function public.check_teacher_invite(raw_code text) returns boolean language sql stable security definer set search_path='' as $body$ select exists(select 1 from public.teacher_invite_codes where code_hash=extensions.digest(convert_to(lower(trim(raw_code)),'UTF8'),'sha256') and used_at is null) $body$;
revoke all on function public.check_teacher_invite(text) from public; grant execute on function public.check_teacher_invite(text) to anon,authenticated;
create or replace function public.activate_teacher_signup(target_user_id uuid,raw_code text) returns void language plpgsql security definer set search_path='' as $body$ declare invite_id uuid; registration public.registration_requests%rowtype; begin select id into invite_id from public.teacher_invite_codes where code_hash=extensions.digest(convert_to(lower(trim(raw_code)),'UTF8'),'sha256') and used_at is null for update; if invite_id is null then raise exception 'invalid teacher invite'; end if; select * into registration from public.registration_requests where user_id=target_user_id and status='pending' and requested_role='teacher' for update; if not found then raise exception 'teacher registration not found'; end if; insert into public.profiles(id,email,role,full_name,phone,address,note,is_active,account_status) values(target_user_id,registration.email,'teacher',registration.full_name,registration.phone,registration.address,registration.note,true,'active'); insert into public.user_roles(user_id,role) values(target_user_id,'teacher'); update public.registration_requests set status='approved',reviewed_at=now(),updated_at=now() where user_id=target_user_id; update public.teacher_invite_codes set used_by=target_user_id,used_at=now() where id=invite_id; end; $body$;
revoke all on function public.activate_teacher_signup(uuid,text) from public; grant execute on function public.activate_teacher_signup(uuid,text) to anon,authenticated;
